#!/usr/bin/env node
/** Parity harness: the JS engines must return the same verdicts as the Python
 * originals on every fixture. Run: node tools/parity.mjs  (exit 1 on divergence)
 *
 * Python verdicts are embedded as expected results, generated by:
 *   python3 aop-spec/validation/validate.py <fixture>   (exit 0 = conformant)
 * and re-verified at generation time by tools/gen-parity.py.
 */
import { readdirSync, readFileSync } from 'node:fs';
import { validateAOP } from '../js/aop-engine.js';

const DATA = new URL('../data/', import.meta.url);
const fixtures = JSON.parse(readFileSync(new URL('fixtures.json', DATA)));

let pass = 0, fail = 0;
const failures = [];

const schema = JSON.parse(readFileSync(new URL('aop-document.schema.json', DATA)));

for (const kind of ['valid', 'invalid', 'adversarial']) {
  for (const fx of fixtures[kind] || []) {
    if (fx.from !== 'aop-spec' && kind !== 'adversarial' && !fx.name.includes('aop')) continue;
    // The conformance fixtures are all AOP documents; aop-spec fixtures too.
    if (kind === 'adversarial' && fx.from !== 'aop-conformance') continue;
    const result = validateAOP(fx.json, schema);
    const expected = kind === 'valid' ? true : false;
    const ok = result.conformant === expected;
    if (ok) pass += 1;
    else {
      fail += 1;
      failures.push(`${kind}/${fx.name}: expected ${expected ? 'CONFORMANT' : 'NONCONFORMANT'}, got ${result.conformant ? 'CONFORMANT' : 'NONCONFORMANT'} — ${result.diagnostics.slice(0, 2).join(' | ')}`);
    }
  }
}

console.log(`PARITY: ${pass} pass, ${fail} fail (of ${pass + fail} fixtures)`);
for (const f of failures) console.log('  DIVERGENCE ' + f);
process.exit(fail ? 1 : 0);
